pub fn classify_password_strength(password: &str) -> &'static str {
    let len = password.len();
    let has_digit = password.chars().any(|c| c.is_ascii_digit());
    if len < 8 {
        "weak"
    } else if len < 12 || !has_digit {
        "medium"
    } else {
        "strong"
    }
}

fn main() {
    println!("{}", classify_password_strength("changeme"));
}

